test('removeLine reports LINE_NOT_FOUND for unknown SKU', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });
  const r2 = removeLine(r1.value, 'UNKNOWN-SKU');
  assert.deepEqual(r2, { ok: false, error: 'LINE_NOT_FOUND' });
});

test('removeLine reports NO_LINES if removing the last line', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });
  const r2 = removeLine(r1.value, 'DEV-HOUR');
  assert.deepEqual(r2, { ok: false, error: 'NO_LINES' });
});

test('removeLine refuses to modify non-draft invoices', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2025-10-07',
    status: 'sent',
    lines: [
      { sku: 'DEV-HOUR', name: 'Development (hour)', qty: 10, unitPrice: 9500, vatRate: 21 },
      { sku: 'LOGO-PACK', name: 'Logo package', qty: 1, unitPrice: 120000, vatRate: 21 },
    ],
  };
  const r = removeLine(invoice, 'DEV-HOUR');
  assert.deepEqual(r, { ok: false, error: 'NOT_DRAFT' });
});

test('removeLine does not mutate original invoice', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  });
  const original = JSON.stringify(r1.value);
  removeLine(r1.value, 'DEV-HOUR');
  assert.equal(JSON.stringify(r1.value), original);
});

test('issueInvoice sets number and status to issued', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });
  const r2 = issueInvoice(r1.value, []);
  assert.equal(r2.ok, true);
  assert.equal(r2.value.number, 'INV-2025-0001');
  assert.equal(r2.value.status, 'issued');
});

test('issueInvoice assigns next number based on existing numbers', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });
  const r2 = issueInvoice(r1.value, ['INV-2025-0001', 'INV-2025-0002']);
  assert.equal(r2.ok, true);
  assert.equal(r2.value.number, 'INV-2025-0003');
});

test('issueInvoice preserves all other fields', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  });
  const r2 = issueInvoice(r1.value, []);
  assert.equal(r2.value.customerId, 'C-001');
  assert.equal(r2.value.issueDate, '2025-10-07');
  assert.equal(r2.value.lines.length, 2);
  assert.equal(r2.value.lines[0].sku, 'DEV-HOUR');
  assert.equal(r2.value.lines[1].sku, 'LOGO-PACK');
});

test('issueInvoice returns NOT_DRAFT if invoice is not draft', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2025-10-07',
    status: 'sent',
    number: 'INV-2025-0001',
    lines: [{ sku: 'DEV-HOUR', name: 'Development (hour)', qty: 10, unitPrice: 9500, vatRate: 21 }],
  };
  const r = issueInvoice(invoice, []);
  assert.deepEqual(r, { ok: false, error: 'NOT_DRAFT' });
});

test('issueInvoice does not mutate original invoice', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });
  const original = JSON.stringify(r1.value);
  issueInvoice(r1.value, []);
  assert.equal(JSON.stringify(r1.value), original);
});

test('issueInvoice handles different years', () => {
  const r1_2024 = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-12-25',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  const r2_2024 = issueInvoice(r1_2024.value, ['INV-2024-0001']);
  assert.equal(r2_2024.value.number, 'INV-2024-0002');

  const r1_2025 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-01',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  const r2_2025 = issueInvoice(r1_2025.value, ['INV-2024-0001', 'INV-2024-0002']);
  assert.equal(r2_2025.value.number, 'INV-2025-0001');
});

test('createInvoice with line discount stores it', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 10 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines[0].discountPercent, 10);
});

test('createInvoice with zero discount does not store it', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 0 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines[0].discountPercent, undefined);
});

test('createInvoice with no discount specified uses tier discount', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });
  assert.equal(r.ok, true);
  // C-002 is standard tier, gets 0% discount (not stored)
  assert.equal(r.value.lines[0].discountPercent, undefined);
});

test('createInvoice rejects negative discount', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: -5 }],
  });
  assert.deepEqual(r, { ok: false, error: 'DISCOUNT_INVALID' });
});

test('createInvoice rejects discount > 100', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 101 }],
  });
  assert.deepEqual(r, { ok: false, error: 'DISCOUNT_INVALID' });
});

test('createInvoice rejects non-numeric discount', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 'ten' }],
  });
  assert.deepEqual(r, { ok: false, error: 'DISCOUNT_INVALID' });
});

test('createInvoice accepts decimal discount', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 12.5 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines[0].discountPercent, 12.5);
});

test('createInvoice accepts discount of exactly 100', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 100 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines[0].discountPercent, 100);
});

test('discountAmount calculates discount correctly', () => {
  const line = {
    sku: 'DEV-HOUR',
    name: 'Development (hour)',
    qty: 10,
    unitPrice: 9500,
    vatRate: 21,
    discountPercent: 10,
  };
  // lineTotal = 10 * 9500 = 95000, discount = 95000 * 10 / 100 = 9500
  assert.equal(discountAmount(line), 9500);
});

test('discountAmount with no discount returns 0', () => {
  const line = {
    sku: 'DEV-HOUR',
    name: 'Development (hour)',
    qty: 10,
    unitPrice: 9500,
    vatRate: 21,
  };
  assert.equal(discountAmount(line), 0);
});

test('discountAmount rounds to nearest cent', () => {
  const line = {
    sku: 'DEV-HOUR',
    name: 'Development (hour)',
    qty: 10,
    unitPrice: 100,
    vatRate: 21,
    discountPercent: 33.33,
  };
  // lineTotal = 10 * 100 = 1000, discount = 1000 * 33.33 / 100 = 333.3 -> 333
  assert.equal(discountAmount(line), 333);
});

test('invoiceTotals returns discount field', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 10 }],
  });
  const totals = invoiceTotals(r.value);
  assert.ok('discount' in totals);
  assert.equal(totals.discount, 9500);
});

test('invoiceTotals with single line and discount', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 10 }],
  });
  const totals = invoiceTotals(r.value);
  // subtotal = 95000, discount = 9500, total = 85500
  assert.equal(totals.subtotal, 95000);
  assert.equal(totals.discount, 9500);
  assert.equal(totals.total, 85500);
});

test('invoiceTotals with multiple lines and different discounts', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 10, discountPercent: 10 },
      { sku: 'LOGO-PACK', qty: 1, discountPercent: 20 },
    ],
  });
  const totals = invoiceTotals(r.value);
  // DEV-HOUR: lineTotal = 95000, discount = 9500
  // LOGO-PACK: lineTotal = 120000, discount = 24000
  // subtotal = 215000, total discount = 33500, total = 181500
  assert.equal(totals.subtotal, 215000);
  assert.equal(totals.discount, 33500);
  assert.equal(totals.total, 181500);
});

test('invoiceTotals with mix of discounted and non-discounted lines', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 10, discountPercent: 10 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  });
  const totals = invoiceTotals(r.value);
  // DEV-HOUR: lineTotal = 95000, discount = 9500
  // LOGO-PACK: lineTotal = 120000, discount = 0
  // subtotal = 215000, total discount = 9500, total = 205500
  assert.equal(totals.subtotal, 215000);
  assert.equal(totals.discount, 9500);
  assert.equal(totals.total, 205500);
});

test('invoiceTotals clamps total to zero when discount exceeds subtotal', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2025-10-07',
    status: 'draft',
    lines: [
      {
        sku: 'DEV-HOUR',
        name: 'Development (hour)',
        qty: 1,
        unitPrice: 100,
        vatRate: 21,
        discountPercent: 100,
      },
    ],
  };
  const totals = invoiceTotals(invoice);
  // subtotal = 100, discount = 100, total should be 0, not -0
  assert.equal(totals.subtotal, 100);
  assert.equal(totals.discount, 100);
  assert.equal(totals.total, 0);
});

test('addLine with discount', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });
