  assert.equal(r2.ok, true);
  assert.equal(r2.value.lines[1].discountPercent, 15);
});

test('addLine rejects invalid discount', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });
  const r2 = addLine(r1.value, { sku: 'LOGO-PACK', qty: 1, discountPercent: 150 });
