test('addLine with zero discount does not store it', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });
  const r2 = addLine(r1.value, { sku: 'LOGO-PACK', qty: 1, discountPercent: 0 });
  assert.equal(r2.ok, true);
  assert.equal(r2.value.lines[1].discountPercent, undefined);
});

test('createInvoice applies gold tier discount automatically', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });
  assert.equal(r.ok, true);
  // C-001 is gold tier, should get 5% discount
  assert.equal(r.value.lines[0].discountPercent, 5);
});

test('createInvoice applies silver tier discount automatically', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });
  assert.equal(r.ok, true);
  // C-003 is silver tier, should get 2.5% discount
  assert.equal(r.value.lines[0].discountPercent, 2.5);
});

test('createInvoice applies standard tier discount (0) automatically', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });
  assert.equal(r.ok, true);
  // C-002 is standard tier, should not store discount (0%)
  assert.equal(r.value.lines[0].discountPercent, undefined);
});

test('createInvoice uses explicit discount instead of tier discount', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 15 }],
  });
  assert.equal(r.ok, true);
  // Explicit discount wins over gold tier 5%
  assert.equal(r.value.lines[0].discountPercent, 15);
});

test('createInvoice uses explicit 0 discount instead of tier discount', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 0 }],
  });
  assert.equal(r.ok, true);
  // Explicit 0 wins over gold tier 5%
  assert.equal(r.value.lines[0].discountPercent, undefined);
});

test('createInvoice with multiple lines each gets tier discount', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  });
  assert.equal(r.ok, true);
  // C-001 is gold tier, all lines should get 5% discount
  assert.equal(r.value.lines[0].discountPercent, 5);
  assert.equal(r.value.lines[1].discountPercent, 5);
});

test('createInvoice with mixed explicit and tier discounts', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'LOGO-PACK', qty: 1, discountPercent: 10 },
    ],
  });
  assert.equal(r.ok, true);
  // First line gets tier discount (5%), second line gets explicit (10%)
  assert.equal(r.value.lines[0].discountPercent, 5);
  assert.equal(r.value.lines[1].discountPercent, 10);
});

test('addLine applies tier discount when no explicit discount given', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });
  const r2 = addLine(r1.value, { sku: 'LOGO-PACK', qty: 1 });
  assert.equal(r2.ok, true);
  // New line should also get gold tier 5% discount
  assert.equal(r2.value.lines[1].discountPercent, 5);
});

test('addLine uses explicit discount instead of tier discount', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });
  const r2 = addLine(r1.value, { sku: 'LOGO-PACK', qty: 1, discountPercent: 20 });
  assert.equal(r2.ok, true);
  // Explicit discount wins over tier discount
  assert.equal(r2.value.lines[1].discountPercent, 20);
});

test('invoiceTotals with tier discount applied', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });
  const totals = invoiceTotals(r.value);
  // gold tier = 5%, so DEV-HOUR 10 * 9500 = 95000, discount = 4750, total = 90250
  assert.equal(totals.subtotal, 95000);
  assert.equal(totals.discount, 4750);
  assert.equal(totals.total, 90250);
});

